<?php
declare(strict_types=1);
ob_start();
require __DIR__.'/../app/bootstrap.php';
$error=''; require ROOT.'/app/actions.php';
$page=(string)($_GET['page']??'home');
if (in_array($page,['home','product','quote','about','process','contact','artist','services'],true)) { require ROOT.'/app/stone.php'; exit; } $u=user();
if ($page==='admin') requireUser(true);
if (in_array($page,['account','orders','checkout','order'],true)) $u=requireUser();
$categories=query('SELECT * FROM categories ORDER BY name')->fetchAll();
function input(string $label,string $name,string $type='text',mixed $value='',bool $required=true): void {
    echo '<label>'.e($label).'<input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'" '.($required?'required':'').'></label>';
}
function startForm(string $action): void { echo '<form method="post">'.token().'<input type="hidden" name="action" value="'.e($action).'">'; }
function card(array $p): void { ?>
<article class="card"><a class="product-art" href="/?page=product&id=<?= $p['id'] ?>"><?php if ($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>" loading="lazy"><?php else: ?><span>◆</span><?php endif ?></a><div class="card-body"><small><?= e($p['category']??'Sản phẩm') ?></small><h3><a href="/?page=product&id=<?= $p['id'] ?>"><?= e($p['name']) ?></a></h3><strong><?= money((int)$p['price']) ?></strong><p class="muted"><?= (int)$p['stock'] ?> sản phẩm có sẵn</p><a class="button secondary" href="/?page=product&id=<?= $p['id'] ?>">Xem sản phẩm →</a></div></article>
<?php }
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đá mỹ nghệ · Quản lý cửa hàng</title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="<?= e(asset('assets/style.css')) ?>"></head><body><div class="topbar">Tư vấn chế tác · Báo giá theo yêu cầu</div><header><a class="brand" href="/">đá<span>mỹ nghệ.</span></a><nav><a href="/">Sản phẩm</a><a href="/?page=cart">Giỏ hàng (<?= array_sum($_SESSION['cart']??[]) ?>)</a><?php if ($u): ?><a href="/?page=orders">Đơn hàng</a><a href="/?page=account"><?= e($u['name']) ?></a><?php if ($u['role']==='admin'): ?><a href="/?page=admin">Quản trị</a><?php endif; startForm('logout'); ?><button class="link">Đăng xuất</button></form><?php else: ?><a href="/?page=login">Đăng nhập</a><?php endif ?></nav></header><main><?php if($error): ?><div role="alert" class="alert"><?= e($error) ?></div><?php endif;
switch ($page): case 'home': ?>
<section class="hero"><div><span class="eyebrow">THIẾT YẾU CHO MỖI NGÀY</span><h1>Chọn điều tốt.<br>Sống đơn giản.</h1><p>Phụ kiện, gia dụng và thời trang dành cho nhịp sống của bạn.</p><a class="button" href="#catalog">Khám phá bộ sưu tập ↗</a></div><div class="hero-art"><span>mộc.</span><p>Ít hơn. Tốt hơn. Mỗi ngày.</p></div></section>
<section id="catalog"><div class="section-title"><h2>Sản phẩm nổi bật</h2><span>Chọn kỹ từng món</span></div><form class="filters" method="get"><input name="q" placeholder="Tìm sản phẩm…" value="<?= e($_GET['q']??'') ?>"><select name="category"><option value="">Tất cả danh mục</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)($c['id'])===(string)($_GET['category']??'')?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><select name="sort"><?php foreach(['new'=>'Mới nhất','asc'=>'Giá tăng dần','desc'=>'Giá giảm dần'] as $key=>$text): ?><option value="<?= $key ?>" <?= ($_GET['sort']??'new')===$key?'selected':'' ?>><?= $text ?></option><?php endforeach ?></select><button>Tìm kiếm</button></form><div class="grid"><?php
$where='p.active=1'; $args=[];
if (!empty($_GET['q'])) { $where.=' AND p.name LIKE ?'; $args[]='%'.substr((string)$_GET['q'],0,200).'%'; }
if (!empty($_GET['category'])) { $where.=' AND p.category_id=?'; $args[]=(int)$_GET['category']; }
$sort=['asc'=>'p.price ASC','desc'=>'p.price DESC','new'=>'p.id DESC'][$_GET['sort']??'new']??'p.id DESC';
$count=(int)query('SELECT COUNT(*) FROM products p WHERE '.$where,$args)->fetchColumn(); $n=max(1,(int)($_GET['n']??1)); $offset=($n-1)*12;
$products=query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE '.$where.' ORDER BY '.$sort.' LIMIT 12 OFFSET '.(int)$offset,$args)->fetchAll();
foreach($products as $p) card($p); if (!$products) echo '<p>Chưa có sản phẩm phù hợp.</p>'; ?></div><div class="pagination"><?php for($i=1;$i<=ceil($count/12);$i++): ?><a class="button secondary" href="/?<?= e(http_build_query(array_merge($_GET,['n'=>$i]))) ?>"><?= $i ?></a><?php endfor ?></div></section>
<?php break; case 'product':
$p=query('SELECT * FROM products WHERE id=? AND active=1',[(int)($_GET['id']??0)])->fetch();
if (!$p) { http_response_code(404); echo '<h1>Không tìm thấy sản phẩm</h1>'; break; } ?>
<div class="detail"><div class="product-art large"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>◆</span><?php endif ?></div><section><span class="eyebrow">MỘC SHOP / SẢN PHẨM</span><h1><?= e($p['name']) ?></h1><h2><?= money((int)$p['price']) ?></h2><p><?= nl2br(e($p['description'])) ?></p><p>Còn <?= (int)$p['stock'] ?> sản phẩm</p><?php startForm('cart'); ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><label>Số lượng<input type="number" name="qty" min="1" max="<?= min(99,(int)$p['stock']) ?>" value="1" required></label><button <?= (int)$p['stock']===0?'disabled':'' ?>>Thêm vào giỏ</button></form><p class="muted">Đổi trả theo chính sách cửa hàng. Thanh toán khi nhận hàng hoặc chuyển khoản.</p></section></div>
<?php break; case 'login': case 'register': ?>
<section class="panel narrow"><h1><?= $page==='login'?'Chào mừng trở lại':'Tạo tài khoản' ?></h1><?php startForm($page); if($page==='register') input('Họ tên','name'); input('Email','email','email'); input('Mật khẩu'.($page==='register'?' (ít nhất 12 ký tự)':''),'password','password'); ?><button>Tiếp tục</button></form><p><a href="/?page=<?= $page==='login'?'register':'login' ?>"><?= $page==='login'?'Chưa có tài khoản? Đăng ký':'Đã có tài khoản? Đăng nhập' ?></a></p></section>
<?php break; case 'cart': case 'checkout': $rows=cart(); $t=totals($rows); ?>
<h1><?= $page==='cart'?'Giỏ hàng':'Thanh toán' ?></h1><div class="detail"><section class="panel"><?php foreach($rows as $p): ?><div class="cart-row"><div><a href="/?page=product&id=<?= $p['id'] ?>"><?= e($p['name']) ?></a><p><?= money((int)$p['price']) ?></p></div><?php startForm('cart'); ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><input aria-label="Số lượng" type="number" name="qty" min="0" max="99" value="<?= $p['qty'] ?>" required><button class="secondary">Cập nhật</button></form></div><?php endforeach; if(!$rows) echo '<p>Giỏ hàng trống. <a href="/">Mua sắm ngay</a></p>'; ?><p class="muted">Đặt số lượng 0 để xóa sản phẩm.</p></section><aside class="panel"><h2>Tóm tắt đơn hàng</h2><p>Tạm tính: <?= money($t['subtotal']) ?></p><p>Vận chuyển: <?= money($t['shipping']) ?></p><h3>Tổng: <?= money($t['total']) ?></h3><?php if($rows && $page==='cart'): ?><a class="button" href="/?page=checkout">Tiến hành đặt hàng →</a><?php elseif($rows): startForm('checkout'); input('Người nhận','name','text',$u['name']); input('Điện thoại','phone','tel'); input('Địa chỉ đầy đủ','address'); input('Mã giảm giá (tính khi đặt hàng)','coupon','text','',false); ?><label>Thanh toán<select name="payment"><option value="cod">Thanh toán khi nhận hàng (COD)</option><option value="bank">Chuyển khoản ngân hàng</option></select></label><p class="muted">Mã giảm giá hợp lệ được trừ trực tiếp vào đơn hàng. Thông tin chuyển khoản hiển thị sau khi đặt.</p><button>Đặt hàng</button></form><?php endif ?></aside></div>
<?php break; case 'account': ?><section class="panel narrow"><h1>Tài khoản</h1><p><?= e($u['email']) ?></p><?php startForm('profile'); input('Họ tên','name','text',$u['name']); input('Mật khẩu hiện tại (khi đổi mật khẩu)','current_password','password','',false); input('Mật khẩu mới (ít nhất 12 ký tự)','password','password','',false); ?><button>Lưu thay đổi</button></form></section>
<?php break; case 'orders': ?><h1>Đơn hàng của tôi</h1><?php $orders=query('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$u['id']])->fetchAll(); require ROOT.'/app/order-table.php'; break;
case 'order':
$o=query('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)])->fetch();
if (!$o || ($u['role']!=='admin' && (int)$o['user_id']!==(int)$u['id'])) { http_response_code(404); echo '<h1>Không tìm thấy đơn hàng</h1>'; break; } ?>
<section class="panel"><span class="eyebrow">ĐƠN HÀNG #<?= $o['id'] ?></span><h1><?= STATUSES[$o['status']] ?></h1><p><?= e($o['name']) ?> · <?= e($o['phone']) ?><br><?= e($o['address']) ?></p><p>Ngày tạo (UTC): <?= e($o['created_at']) ?></p><div class="table-wrap"><table><tr><th>Sản phẩm</th><th>Số lượng</th><th>Thành tiền</th></tr><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $item): ?><tr><td><?= e($item['name']) ?></td><td><?= $item['qty'] ?></td><td><?= money((int)$item['price']*(int)$item['qty']) ?></td></tr><?php endforeach ?></table></div><p>Tạm tính: <?= money((int)$o['subtotal']) ?> · Giảm giá: <?= money((int)$o['discount']) ?> · Phí giao: <?= money((int)$o['shipping']) ?></p><h2>Tổng cộng <?= money((int)$o['total']) ?></h2><p><?= $o['payment']==='cod'?'Thanh toán khi nhận hàng':'Chuyển khoản ngân hàng' ?> · <?= $o['paid']?'Đã thanh toán':'Chưa xác nhận thanh toán' ?></p><?php if($o['payment']==='bank'): ?><p><?= e(getenv('BANK_INSTRUCTIONS') ?: 'Cửa hàng sẽ liên hệ cung cấp thông tin tài khoản ngân hàng.') ?> Nội dung: DH<?= $o['id'] ?>.</p><?php endif; if($u['role']==='admin'): startForm('status'); ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><label>Trạng thái tiếp theo<select name="status"><?php foreach(STATUSES as $s=>$label): ?><option value="<?= $s ?>"><?= $label ?></option><?php endforeach ?></select></label><button>Cập nhật trạng thái</button></form><?php startForm('paid'); ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><button class="secondary">Đổi xác nhận thanh toán</button></form><?php endif ?></section>
<?php break; case 'admin': require ROOT.'/app/admin.php'; break; default: http_response_code(404); ?><h1>Trang không tồn tại</h1><?php endswitch ?></main><footer><a class="brand" href="/">đá<span>mỹ nghệ.</span></a><p>Tượng đá · Linh vật · Đồ thờ · Cảnh quan.</p><p>Thông tin liên hệ, chính sách giao hàng và đổi trả cần được cửa hàng cấu hình trước khi mở bán.</p></footer></body></html>
